using GastricCancerDetection.Infrastructure.Persistence; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace GastricCancerDetection.Api.Controllers; [ApiController][Route("api/candidates")] public class CandidatesController:ControllerBase { private readonly GastricCancerDbContext _db; public CandidatesController(GastricCancerDbContext db)=>_db=db; [HttpGet] public async Task<IActionResult> Get([FromQuery]int? runId=null,[FromQuery]string? featureType=null){var q=_db.Candidates.AsNoTracking();if(runId.HasValue)q=q.Where(x=>x.AnalysisRunId==runId);if(!string.IsNullOrWhiteSpace(featureType))q=q.Where(x=>x.FeatureType==featureType);return Ok(await q.OrderByDescending(x=>x.OverallPriority).Take(500).ToListAsync());} [HttpGet("{id:long}")] public async Task<IActionResult> Get(long id){var x=await _db.Candidates.AsNoTracking().FirstOrDefaultAsync(x=>x.CandidateId==id);return x==null?NotFound():Ok(x);} [HttpGet("{id:long}/evidence")] public async Task<IActionResult> Evidence(long id){return Ok(await _db.CandidateEvidence.AsNoTracking().Where(x=>x.CandidateId==id).ToListAsync());} [HttpGet("{id:long}/cfDNA-score")] public async Task<IActionResult> CfDNA(long id){return Ok(await _db.CfDNADetectabilityScores.AsNoTracking().Where(x=>x.CandidateId==id).OrderByDescending(x=>x.Id).FirstOrDefaultAsync());} }
